using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class BMElectrical {public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit required");var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Afrer_Seconds/05.Model/Props/B5/Materials/Props_ElectricalCabinet_URP.mat");if(!mat)throw new Exception("Missing PBR");int n=0;var root=s.GetRootGameObjects().Single(g=>g.name=="B2_MachineryNetwork");foreach(var t in root.GetComponentsInChildren<Transform>().Where(t=>t.name.EndsWith("_Visual")&&t.name.Contains("ElectricalCabinet")))foreach(var r in t.GetComponentsInChildren<MeshRenderer>()){r.sharedMaterials=r.sharedMaterials.Select(m=>mat).ToArray();PrefabUtility.RecordPrefabInstancePropertyModifications(r);n++;}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{pbrCabinets=n};}}
